from part1 import add, P

add(id="suebi", name="Suebic Kingdom of Galicia", type="kingdom", yearsActive="409–585",
 summary="A Germanic people who crossed the Rhine in 406 and founded a kingdom in Roman Gallaecia (north-west Iberia), with its capital at Braga, until the Visigoth Leovigild annexed it in 585.",
 description="The Suebi, with Vandals and Alans, entered Spain in 409 and took the north-west. Under Rechiar they raided far across the peninsula until the Visigoths defeated them in 456. The kingdom recovered and converted to Catholicism under Martin of Braga's guidance in the 560s, then fell to Leovigild in 585.",
 conflicts="Defeat by the Visigoth Theodoric II at the river Órbigo (456); conquest by Leovigild (585).",
 leaders="Hermeric (409–438); Rechiar (448–456), the first Catholic Germanic king; Chararic and Theodemar (mid-6th century); Andeca (584–585).",
 religion="Briefly Catholic under Rechiar, then Arian, then Catholic again in the 560s through Martin of Braga, who held church councils at Braga (561, 572).",
 culture="A small Suebic warrior elite ruled Hispano-Roman Gallaecians from Braga and Lugo. They struck their own coins in the Roman style.",
 literature="Bishop Hydatius of Aquae Flaviae chronicled their raids. Martin of Braga's On the Correction of Rustics attacked lingering pagan customs.",
 art="Little survives beyond coins and church foundations at Braga and Dumio.",
 ideas="Martin of Braga's Formula vitae honestae adapted Seneca's Stoic ethics for Christian rulers.",
 science="Martin's sermon records peasant calendars and day-names, part of the reason Portuguese numbers its weekdays instead of naming them after gods.",
 story=[{"title":"Monday is 'Second Day'","text":"Martin of Braga scolded peasants for naming days after Mars, Mercury and Jupiter. Portuguese alone among Romance languages took his advice: Monday is segunda-feira, 'second day', and so on through the week."}],
 images=[("Braga cathedral","Braga Cathedral, in the old Suebic capital","culture"),
         ("Suevic tremissis","Suevic gold coin","art")],
 sources="Encyclopaedia Britannica, 'Suebi'; R. Collins, Early Medieval Spain (1995).")

add(id="saxons", name="Old Saxons", type="tribal confederation", yearsActive="c. 400–804",
 summary="Germanic tribes between the Rhine and the Elbe, some of whom sailed to Britain, while those at home resisted the Franks until Charlemagne's wars of 772–804.",
 description="Saxons raided Roman coasts from the third century and joined Angles and Jutes in settling Britain in the fifth. The continental Saxons stayed pagan and without kings, ruled by regional leaders and an assembly at Marklo. Charlemagne's thirty-year war, led on the Saxon side by Widukind, ended with forced baptism and integration into the Frankish realm; a century later the Saxon Ottonians would rule Germany.",
 conflicts="Charlemagne destroyed the sacred Irminsul pillar (772); Widukind's revolts led to the executions at Verden (782). Widukind was baptized in 785; resistance ended in 804.",
 leaders="Widukind (fl. 777–785), war leader and later a convert.",
 religion="Pagan, worshipping at the Irminsul and sacred groves, until forced conversion. Charlemagne's Capitulary for Saxony made refusing baptism punishable by death.",
 culture="Free farmers, nobles and half-free laeti met in a general assembly. Their language, Old Saxon, is the ancestor of Low German.",
 literature="The Heliand (c. 830) retold the Gospels as an Old Saxon epic with Christ as a lord and his disciples as retainers.",
 art="Brooches and cemetery finds from the Elbe-Weser area; after conversion, monasteries such as Corvey (founded 822).",
 ideas="The Heliand shows a missionary method: presenting Christian ideas in the familiar language of loyalty to a lord.",
 science="Monastic schools at Corvey and Fulda brought Latin learning to Saxony after conversion.",
 story=[{"title":"Christ the Chieftain","text":"In the Heliand the Sermon on the Mount is delivered to warriors gathered round their lord, and Peter cuts off the servant's ear with the fury of a thane defending his chief."}],
 images=[("Heliand manuscript","Heliand manuscript, the Old Saxon Gospel epic","culture"),
         ("Corvey Westwerk","Westwork of Corvey Abbey (873–885)","art")],
 sources="Encyclopaedia Britannica, 'Saxon'; I. Wood, The Missionary Life (2001).")

add(id="thuringians", name="Kingdom of the Thuringians", type="kingdom", yearsActive="c. 450–531",
 summary="A Germanic kingdom in central Germany between the Harz and the Danube, destroyed by the Franks and Saxons in 531.",
 description="The Thuringian kingdom grew in the late fifth century and allied with Theodoric's Ostrogoths by marriage. In 531 Frankish kings Theuderic I and Chlothar I defeated King Herminafrid on the Unstrut, and Thuringia became a Frankish duchy. Princess Radegund, carried off as a captive, became Chlothar's queen and later a saint.",
 conflicts="Frankish conquest after the battle on the Unstrut (531).",
 leaders="Bisinus (late 5th century); Herminafrid (d. c. 534), married to Theodoric's niece Amalaberga.",
 religion="Largely pagan; converted under Frankish rule and by Boniface's mission in the eighth century.",
 culture="Their burials show horses and fine metalwork; the Thuringian name survives in the modern German state.",
 literature="Venantius Fortunatus wrote 'The Fall of Thuringia' as a lament in Radegund's voice.",
 art="Bow brooches of the Thuringian style.",
 ideas="Radegund's convent at Poitiers, the Holy Cross, became a centre of learning and relic devotion.",
 science="Little is recorded.",
 story=[{"title":"Radegund's Lament","text":"Taken captive as a child after the Unstrut, Radegund was married to her family's conqueror. She later left him, founded a convent at Poitiers and had the poet Fortunatus write her grief for her lost homeland."}],
 images=[("Radegund Poitiers manuscript","Saint Radegund, Thuringian princess, in an 11th-century manuscript","culture"),
         ("Abbaye Sainte-Croix Poitiers","Holy Cross abbey, Poitiers, founded by Radegund","art")],
 sources="Encyclopaedia Britannica, 'Thuringia'; I. Wood, The Merovingian Kingdoms (1994).")

add(id="frisians", name="Frisian Kingdom", type="kingdom", yearsActive="c. 600–734",
 summary="Seafaring Germanic people of the North Sea coast whose kings controlled the trade of the Rhine delta until the Franks conquered them in 734.",
 description="Frisians lived on terps, artificial mounds in the tidal marshes, and traded cloth, slaves and wine along the North Sea. King Redbad resisted Frankish expansion and Christian missions around 700. Charles Martel's victory at the Boarn (734) ended independence, and the trading town of Dorestad became one of the busiest ports of Carolingian Europe.",
 conflicts="Pippin of Herstal defeated Redbad at Dorestad (c. 689); Charles Martel conquered Frisia at the Boarn (734). Frisians killed the missionary Boniface at Dokkum (754).",
 leaders="Aldgisl (fl. 678); Redbad (d. 719).",
 religion="Pagan, worshipping Fosite on Heligoland; missions by Willibrord, first bishop of Utrecht (695), and Boniface.",
 culture="Terp villages, cattle and sea trade. Frisian sceattas (silver coins) circulated across the North Sea. Old Frisian is the closest relative of English.",
 literature="Lex Frisionum (c. 790) recorded their law under Charlemagne.",
 art="Silver sceattas with Wodan heads and monster motifs.",
 ideas="Their trading network linked England, Scandinavia and the Rhineland into one North Sea economy.",
 science="Terp-building and dike work were early forms of the land reclamation the Low Countries would master.",
 story=[{"title":"Redbad at the Font","text":"Legend says Redbad was about to be baptized when he asked whether his ancestors were in heaven. Told they were in hell, he stepped back, saying he would rather be with his forefathers than with a few paupers in heaven."}],
 images=[("terp Friesland","A terp mound in Friesland","culture"),
         ("Frisian sceat","Frisian silver sceat coin","art")],
 sources="Encyclopaedia Britannica, 'Frisian'; S. Lebecq, Marchands et navigateurs frisons (1983).")

add(id="anglo-saxons", name="Anglo-Saxon kingdoms", type="kingdoms",
 yearsActive="c. 450–927 (until a single English kingdom)",
 nameByTick={"800":"Anglo-Saxon kingdoms (Mercia, Wessex, Northumbria, Kent)","900":"Anglo-Saxon kingdoms (Wessex, English Mercia)"},
 summary="The Germanic kingdoms of lowland Britain—Kent, Northumbria, Mercia, Wessex and others—from the fifth-century settlements until Wessex united England in 927.",
 description="After Roman rule ended around 410, Angles, Saxons and Jutes settled eastern Britain and formed kingdoms. Kent received Augustine's mission in 597, Northumbria produced Bede and the Lindisfarne Gospels, and Mercia under Offa (757–796) dominated the south and built Offa's Dyke. Viking armies destroyed Northumbria, East Anglia and half of Mercia in the 860s–870s. Alfred of Wessex held out, and his children and grandson Æthelstan reconquered the Danelaw, creating the kingdom of England.",
 conflicts="Battle of Mount Badon against the Britons (c. 500); Northumbrian victory at Catraeth (c. 600); Mercian wars under Penda (d. 655). The Great Heathen Army (865) and Alfred's victory at Edington (878).",
 leaders="Æthelberht of Kent (d. 616); Edwin and Oswald of Northumbria; Penda and Offa of Mercia; Alfred the Great of Wessex (871–899); Edward the Elder (899–924).",
 religion="Pagan until the Roman mission to Kent (597) and the Irish mission from Iona to Northumbria (635). The Synod of Whitby (664) chose Roman over Irish customs.",
 culture="Hall society of lords, thegns and ceorls, with wergild and law codes from Æthelberht onward. Burhs, Alfred's fortified towns, organized defence.",
 literature="Bede's Ecclesiastical History of the English People (731); Beowulf; Cædmon's Hymn, the oldest English poem; Alfred's translations of Latin works and the Anglo-Saxon Chronicle.",
 art="The Sutton Hoo ship burial (early 7th century); the Lindisfarne Gospels (c. 715); the Ruthwell Cross; the Staffordshire Hoard.",
 ideas="Bede popularized dating years Anno Domini. Alfred's preface to Pastoral Care argued that learning should be translated into English so free men could read.",
 science="Bede's The Reckoning of Time explained tides and the computus of Easter.",
 story=[{"title":"The Sparrow in the Hall","text":"At King Edwin's council in 627, a counsellor compared human life to a sparrow that flies in from winter through a warm, lit hall and out again into the dark. If the new religion could tell them more, he said, they should follow it."}],
 images=[("Sutton Hoo helmet","Sutton Hoo helmet (early 7th century)","art"),
         ("Lindisfarne Gospels folio","Lindisfarne Gospels (c. 715)","culture"),
         ("Offa's Dyke","Offa's Dyke, the earthwork boundary of Mercia","culture")],
 sources="Encyclopaedia Britannica, 'Anglo-Saxon'; F. Stenton, Anglo-Saxon England (1943); J. Campbell (ed.), The Anglo-Saxons (1982).")

add(id="britons", name="Brittonic kingdoms (Wales, Dumnonia, Brittany)", type="kingdoms", yearsActive="c. 410–10th century",
 summary="The Celtic-speaking British kingdoms of western Britain—Gwynedd, Powys, Dumnonia and the north—and their offshoot across the Channel in Brittany.",
 description="When Roman authority ended, Britons formed kingdoms in Wales, Cornwall and Devon (Dumnonia), Cumbria and Strathclyde. Some migrated to Armorica, which became Brittany. Over the sixth to ninth centuries the Anglo-Saxons pushed them west. Brittany under Nominoë and Erispoë defeated Charles the Bald at Jengland (851) and became a kingdom.",
 conflicts="Mount Badon (c. 500); defeat at Catraeth (c. 600) and Chester (c. 615); Breton victory at Jengland (851).",
 leaders="Maelgwn Gwynedd (d. c. 547); Cadwallon ap Cadfan (d. 634); Rhodri the Great of Gwynedd (844–878); Nominoë of Brittany (d. 851).",
 religion="Christian since Roman times, with a strong monastic tradition (St David, St Samson of Dol).",
 culture="Brittonic speech developed into Welsh, Cornish, Cumbric and Breton. Kin-based society with praise poets at court.",
 literature="Gildas's On the Ruin of Britain (6th century); Y Gododdin by Aneirin; the Historia Brittonum (c. 829), first to name Arthur as a war leader.",
 art="Inscribed stones and early Christian crosses in Wales and Cornwall.",
 ideas="The Historia Brittonum created the Arthur legend that would sweep medieval Europe.",
 science="Monastic schools such as Llanilltud Fawr kept Latin learning.",
 story=[{"title":"Three Hundred Went to Catraeth","text":"Y Gododdin mourns warriors from around Edinburgh who feasted for a year, then rode against the Angles at Catraeth. Of three hundred, the poem says, only one came back."}],
 images=[("Y Gododdin Book of Aneirin","Book of Aneirin, containing Y Gododdin","culture"),
         ("Tintagel Castle","Tintagel, a high-status site of Dumnonia","art")],
 sources="Encyclopaedia Britannica, 'Wales: history', 'Brittany'; T. Charles-Edwards, Wales and the Britons 350–1064 (2013).")

add(id="picts-scots", name="Picts and Scots of Dál Riata", type="kingdoms", yearsActive="c. 300–900 (Alba from c. 900)",
 summary="The Picts of eastern and northern Scotland and the Gaelic kingdom of Dál Riata in Argyll, which merged into the kingdom of Alba around 900.",
 description="The Picts, descendants of Iron Age Caledonians, defeated Northumbria at Nechtansmere (685). Dál Riata, settled from Ulster, held Argyll and the island monastery of Iona, founded by Columba in 563. Viking attacks weakened both, and Cináed mac Ailpín (Kenneth MacAlpin) became king of the Picts around 843; by 900 the Gaelic kingdom of Alba had absorbed Pictland.",
 conflicts="Nechtansmere (685); Viking defeat of the Picts (839).",
 leaders="Bridei son of Beli (fl. 685); Óengus son of Fergus (729–761); Cináed mac Ailpín (d. 858).",
 religion="Christianized from Iona and Northumbria; Columba's monastery was the mother house for missions across northern Britain.",
 culture="Pictish symbol stones; matrilineal royal succession is debated. Gaelic language gradually replaced Pictish.",
 literature="Adomnán's Life of Columba (c. 700); the Book of Kells may have been begun on Iona.",
 art="Pictish symbol stones with crescents, V-rods and beasts (Aberlemno); silver hoards such as St Ninian's Isle.",
 ideas="Adomnán's Law of the Innocents (697) protected women, children and clerics in war.",
 science="Iona's scribes kept annals that are among the earliest records in the British Isles.",
 story=[{"title":"The Beast in the River Ness","text":"Adomnán tells how Columba, crossing the River Ness, ordered a water beast that had killed a man to go back. It fled, which is the first written mention of a monster near Loch Ness."}],
 images=[("Aberlemno Pictish stone","Aberlemno Pictish cross-slab","art"),
         ("Iona Abbey","Iona Abbey, on the site of Columba's monastery","culture")],
 sources="Encyclopaedia Britannica, 'Pict', 'Dál Riata'; A. Woolf, From Pictland to Alba (2007).")

add(id="irish", name="Irish kingdoms", type="kingdoms", yearsActive="c. 400–1169",
 summary="Ireland's many small kingdoms under provincial over-kings, which became a centre of monastic learning and sent missionaries across Europe.",
 description="Early medieval Ireland was divided into perhaps 150 túatha under kings of Ulster, Connacht, Leinster and Munster, with the Uí Néill claiming the high-kingship at Tara. Patrick's fifth-century mission began a monastic culture at Armagh, Clonmacnoise and Kildare. Irish monks such as Columbanus founded houses at Luxeuil and Bobbio. Vikings raided from 795 and founded Dublin (841).",
 conflicts="Dynastic wars among the Uí Néill, Eóganachta and others; Viking raids from 795.",
 leaders="Niall of the Nine Hostages (legendary, 5th century); Máel Sechnaill I (846–862), high king who fought the Vikings.",
 religion="Christian from Patrick's mission (5th century); abbots of great monasteries were powerful lords.",
 culture="Brehon law, with fosterage, honour-price and professional poets (filid). Ogham inscriptions on stones.",
 literature="Táin Bó Cúailnge; Patrick's Confessio; monastic annals; early Irish lyric poetry.",
 art="Book of Kells (c. 800); Ardagh Chalice; Tara Brooch; high crosses at Monasterboice.",
 ideas="Irish penitentials introduced private confession. John Scotus Eriugena was the leading philosopher of ninth-century Europe.",
 science="Irish computists and the geographer Dicuil (825) recorded voyages to Iceland.",
 story=[{"title":"Pangur Bán","text":"In the margin of a ninth-century manuscript an Irish monk wrote a poem about his white cat: the cat hunts mice and he hunts meanings, each content in his own work."}],
 images=[("Book of Kells Chi Rho","Chi-Rho page, Book of Kells (c. 800)","art"),
         ("Ardagh Chalice","Ardagh Chalice (8th century)","culture")],
 sources="Encyclopaedia Britannica, 'Ireland: early history'; D. Ó Cróinín, Early Medieval Ireland 400–1200 (1995).")

add(id="basques", name="Duchy of Vasconia", type="duchy", yearsActive="602–c. 819 (Pamplona kingdom from 824)",
 summary="The Basque-speaking lands on both sides of the western Pyrenees, a duchy under nominal Frankish rule whose people ambushed Charlemagne's rearguard at Roncevaux (778).",
 description="Basques resisted Visigoths, Franks and Arabs alike. The Franks created a duchy of Vasconia in 602, which often acted independently. In 778 Basques destroyed Charlemagne's rearguard at Roncevaux, and in 824 Íñigo Arista founded the kingdom of Pamplona, later Navarre.",
 conflicts="Visigothic campaigns; Roncevaux (778); second Roncevaux (824).",
 leaders="Duke Lupus II (late 8th century); Íñigo Arista of Pamplona (824–851).",
 religion="Christianized slowly; pagan practices persisted in the mountains.",
 culture="Basque, a pre-Indo-European language, survived here. Shepherd and farming communities in the valleys.",
 literature="The Song of Roland (c. 1100) remembers Roncevaux but changes the Basques into Saracens.",
 art="Little survives from this period.",
 ideas="Their persistent self-rule laid the base for the fueros (local liberties) of later Basque provinces.",
 science="Not recorded.",
 story=[{"title":"Roland's Horn","text":"Einhard records that in 778 Basques ambushed the Frankish baggage train in the Pyrenees, killing Roland, prefect of the Breton March. Three centuries later the Song of Roland made it a stand against a Saracen host, with Roland blowing his horn too late."}],
 images=[("Roncesvalles","Roncevaux Pass in the Pyrenees","culture"),
         ("Breaking of the sword Durendal","Roland at Roncevaux, from a manuscript","art")],
 sources="Encyclopaedia Britannica, 'Basque', 'Battle of Roncesvalles'; R. Collins, The Basques (1986).")
